    plan: { en: "Use the same set-up against nearly everything: d4, Bf4, e3, Nf3, c3, Nbd2 and Bd3. Then put a knight on e5, back it up with f4, and attack the king with the queen on f3 or h3 and the bishop on d3 aiming at h7.", pa: "ਲਗਭਗ ਹਰ ਚਾਲ ਦੇ ਵਿਰੁੱਧ ਇੱਕੋ ਜਿਹੀ ਤਿਆਰੀ ਵਰਤੋ: d4, Bf4, e3, Nf3, c3, Nbd2 ਅਤੇ Bd3। ਫਿਰ e5 ਉੱਤੇ ਘੋੜਾ ਰੱਖੋ, f4 ਨਾਲ ਉਸ ਨੂੰ ਸਹਾਰਾ ਦਿਓ, ਅਤੇ f3 ਜਾਂ h3 ਵਾਲੀ ਰਾਣੀ ਅਤੇ h7 ਵੱਲ ਤਾਣੇ d3 ਵਾਲੇ ਊਠ ਨਾਲ ਬਾਦਸ਼ਾਹ ਉੱਤੇ ਹਮਲਾ ਕਰੋ।" },
