        1: { en: "Black meets it head on.", pa: "ਕਾਲਾ ਸਿੱਧਾ ਸਾਹਮਣਾ ਕਰਦਾ ਹੈ।" },
        2: { en: "The London bishop comes out first, before e3 can shut it in.", pa: "ਲੰਡਨ ਵਾਲਾ ਊਠ ਪਹਿਲਾਂ ਬਾਹਰ ਆਉਂਦਾ ਹੈ, ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ e3 ਉਸ ਨੂੰ ਬੰਦ ਕਰ ਦੇਵੇ।" },
