        6: { en: "Develop the knight. It also watches e5, a key square in the London.", pa: "ਘੋੜਾ ਬਾਹਰ ਕੱਢੋ। ਇਹ e5 ਉੱਤੇ ਵੀ ਨਜ਼ਰ ਰੱਖਦਾ ਹੈ, ਜੋ ਲੰਡਨ ਪ੍ਰਣਾਲੀ ਦਾ ਇੱਕ ਖ਼ਾਸ ਖ਼ਾਨਾ ਹੈ।" },
