        8: { en: "Hold d4 with a pawn. The pawns on c3, d4 and e3 are the London wall.", pa: "d4 ਨੂੰ ਪਿਆਦੇ ਨਾਲ ਸੰਭਾਲੋ। c3, d4 ਅਤੇ e3 ਵਾਲੇ ਪਿਆਦੇ ਲੰਡਨ ਪ੍ਰਣਾਲੀ ਦੀ ਕੰਧ ਹਨ।" },
        10: { en: "The other knight goes to d2, ready to back up e5.", pa: "ਦੂਜਾ ਘੋੜਾ d2 ਉੱਤੇ ਜਾਂਦਾ ਹੈ, e5 ਨੂੰ ਸਹਾਰਾ ਦੇਣ ਲਈ ਤਿਆਰ।" },
