        27: { en: "Black finally strikes in the centre.", pa: "ਆਖ਼ਰ ਕਾਲਾ ਕੇਂਦਰ ਵਿੱਚ ਵਾਰ ਕਰਦਾ ਹੈ।" },
        28: { en: "Push past: the pawn on d5 cramps Black.", pa: "ਅੱਗੇ ਲੰਘ ਜਾਓ: d5 ਵਾਲਾ ਪਿਆਦਾ ਕਾਲੇ ਨੂੰ ਤੰਗ ਕਰਦਾ ਹੈ।" },
        30: { en: "The knight steps back and attacks e4.", pa: "ਘੋੜਾ ਪਿੱਛੇ ਹਟਦਾ ਹੈ ਅਤੇ e4 ਉੱਤੇ ਹਮਲਾ ਕਰਦਾ ਹੈ।" },
