    plan: { en: "Play ...c6 and ...d5, swap on e4, and bring the bishop to f5 before ...e6. Keep a solid chain of pawns (c6, e6, f7), develop the knights to d7 and f6, castle, then free your game with ...c5.", pa: "...c6 ਅਤੇ ...d5 ਚੱਲੋ, e4 ਉੱਤੇ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ, ਅਤੇ ...e6 ਤੋਂ ਪਹਿਲਾਂ ਊਠ ਨੂੰ f5 ਉੱਤੇ ਲਿਆਓ। ਪਿਆਦਿਆਂ ਦੀ ਪੱਕੀ ਲੜੀ (c6, e6, f7) ਬਣਾਈ ਰੱਖੋ, ਘੋੜਿਆਂ ਨੂੰ d7 ਅਤੇ f6 ਉੱਤੇ ਬਾਹਰ ਕੱਢੋ, ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ, ਫਿਰ ...c5 ਨਾਲ ਆਪਣੀ ਖੇਡ ਨੂੰ ਖੁੱਲ੍ਹਾ ਕਰੋ।" },
