        1: { en: "Get ready for ...d5, with a pawn to back it up.", pa: "...d5 ਲਈ ਤਿਆਰੀ ਕਰੋ, ਜਿਸ ਨੂੰ ਸਹਾਰਾ ਦੇਣ ਲਈ ਇੱਕ ਪਿਆਦਾ ਹੈ।" },
