        7: { en: "The bishop comes out before ...e6 can shut it in, and hits the knight.", pa: "...e6 ਦੇ ਊਠ ਨੂੰ ਬੰਦ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਊਠ ਬਾਹਰ ਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਘੋੜੇ ਉੱਤੇ ਵਾਰ ਕਰਦਾ ਹੈ।" },
