        10: { en: "White chases it with the h-pawn.", pa: "ਚਿੱਟਾ h ਵਾਲੇ ਪਿਆਦੇ ਨਾਲ ਉਸ ਨੂੰ ਭਜਾਉਂਦਾ ਹੈ।" },
