        9: { en: "Castle early: your king is safe.", pa: "ਛੇਤੀ ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ: ਤੁਹਾਡਾ ਬਾਦਸ਼ਾਹ ਸੁਰੱਖਿਅਤ ਹੈ।" },
