        13: { en: "Get ready for ...Be6 or ...Bb7: this is the Tartakower set-up.", pa: "...Be6 ਜਾਂ ...Bb7 ਲਈ ਤਿਆਰੀ ਕਰੋ: ਇਹ ਤਾਰਤਾਕੋਵਰ ਤਿਆਰੀ ਹੈ।" },
        14: { en: "White swaps in the centre.", pa: "ਚਿੱਟਾ ਕੇਂਦਰ ਵਿੱਚ ਅਦਲਾ-ਬਦਲੀ ਕਰਦਾ ਹੈ।" },
        15: { en: "Take back with the knight, and offer swaps.", pa: "ਘੋੜੇ ਨਾਲ ਬਦਲੇ ਵਿੱਚ ਮਾਰ ਲਓ, ਅਤੇ ਅਦਲਾ-ਬਦਲੀ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰੋ।" },
        16: { en: "White swaps bishops.", pa: "ਚਿੱਟਾ ਊਠਾਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਰਦਾ ਹੈ।" },
