        4: { en: "White chases the queen with a developing move.", pa: "ਚਿੱਟਾ ਮੋਹਰਾ ਬਾਹਰ ਕੱਢਦੇ ਹੋਏ ਰਾਣੀ ਨੂੰ ਭਜਾਉਂਦਾ ਹੈ।" },
