    plan: { en: "Pin White's knight on c3 with ...Bb4 so it cannot help push e4. Castle early, take your share of the centre with ...d5 and ...c5, swap on c4 so White's bishop moves twice, and keep the pin with ...Ba5 when White plays a3.", pa: "...Bb4 ਨਾਲ c3 ਵਾਲੇ ਚਿੱਟੇ ਘੋੜੇ ਨੂੰ ਪਿੰਨ ਕਰੋ ਤਾਂ ਜੋ ਉਹ e4 ਚੱਲਣ ਵਿੱਚ ਮਦਦ ਨਾ ਕਰ ਸਕੇ। ਛੇਤੀ ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ, ...d5 ਅਤੇ ...c5 ਨਾਲ ਕੇਂਦਰ ਵਿੱਚੋਂ ਆਪਣਾ ਹਿੱਸਾ ਲਓ, c4 ਉੱਤੇ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ ਤਾਂ ਜੋ ਚਿੱਟੇ ਦੇ ਊਠ ਨੂੰ ਦੋ ਵਾਰ ਚੱਲਣਾ ਪਵੇ, ਅਤੇ ਜਦੋਂ ਚਿੱਟਾ a3 ਚੱਲੇ ਤਾਂ ...Ba5 ਨਾਲ ਪਿੰਨ ਕਾਇਮ ਰੱਖੋ।" },
