    plan: { en: "Play d4 and c4, then put the bishop on g2 so it looks down the long diagonal at b7. Castle. If Black takes on c4, win the pawn back with Qc2 and Qxc4, then finish development with Bd2 and the rooks.", pa: "d4 ਅਤੇ c4 ਚੱਲੋ, ਫਿਰ ਊਠ ਨੂੰ g2 ਉੱਤੇ ਰੱਖੋ ਤਾਂ ਜੋ ਉਹ ਲੰਮੇ ਤਿਰਛੇ ਰਾਹ ਰਾਹੀਂ b7 ਨੂੰ ਵੇਖੇ। ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ। ਜੇ ਕਾਲਾ c4 ਉੱਤੇ ਮਾਰ ਲਵੇ, ਤਾਂ Qc2 ਅਤੇ Qxc4 ਨਾਲ ਪਿਆਦਾ ਵਾਪਸ ਜਿੱਤ ਲਓ, ਫਿਰ Bd2 ਅਤੇ ਹਾਥੀਆਂ ਨਾਲ ਮੋਹਰੇ ਬਾਹਰ ਕੱਢਣੇ ਪੂਰੇ ਕਰੋ।" },
