    about: { en: "1.e4 d6 2.d4 Nf6 3.Nc3 g6: let White take the centre, keep a flexible shape and hit back later.", pa: "1.e4 d6 2.d4 Nf6 3.Nc3 g6: ਚਿੱਟੇ ਨੂੰ ਕੇਂਦਰ ਉੱਤੇ ਕਬਜ਼ਾ ਕਰਨ ਦਿਓ, ਲਚਕੀਲੀ ਤਿਆਰੀ ਰੱਖੋ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਜਵਾਬੀ ਵਾਰ ਕਰੋ।" },
    plan: { en: "Play ...d6, ...Nf6, ...g6 and ...Bg7, and castle. The bishop on g7 watches the centre from afar. Play ...c6 and ...a5 to stop White gaining space on the queenside, and bring a knight to a6 on its way to b4.", pa: "...d6, ...Nf6, ...g6 ਅਤੇ ...Bg7 ਚੱਲੋ, ਅਤੇ ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ। g7 ਵਾਲਾ ਊਠ ਦੂਰੋਂ ਕੇਂਦਰ ਉੱਤੇ ਨਜ਼ਰ ਰੱਖਦਾ ਹੈ। ਚਿੱਟੇ ਨੂੰ ਰਾਣੀ ਵਾਲੇ ਪਾਸੇ ਥਾਂ ਲੈਣ ਤੋਂ ਰੋਕਣ ਲਈ ...c6 ਅਤੇ ...a5 ਚੱਲੋ, ਅਤੇ ਇੱਕ ਘੋੜੇ ਨੂੰ b4 ਦੇ ਰਾਹ ਵਿੱਚ a6 ਉੱਤੇ ਲਿਆਓ।" },
