    about: { en: "1.d4 Nf6 2.c4 g6 3.Nc3 d5: let White build a big centre, then attack it with your pieces.", pa: "1.d4 Nf6 2.c4 g6 3.Nc3 d5: ਚਿੱਟੇ ਨੂੰ ਵੱਡਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਿਓ, ਫਿਰ ਆਪਣੇ ਮੋਹਰਿਆਂ ਨਾਲ ਉਸ ਉੱਤੇ ਹਮਲਾ ਕਰੋ।" },
    plan: { en: "Strike with ...d5 and swap knights on c3, so White's centre is big but loose. Hit d4 with the bishop on g7, ...c5 and the queen. Castle, swap on d4, swap queens, and put a rook on the d-file.", pa: "...d5 ਨਾਲ ਵਾਰ ਕਰੋ ਅਤੇ c3 ਉੱਤੇ ਘੋੜਿਆਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ, ਤਾਂ ਜੋ ਚਿੱਟੇ ਦਾ ਕੇਂਦਰ ਵੱਡਾ ਪਰ ਢਿੱਲਾ ਹੋ ਜਾਵੇ। g7 ਵਾਲੇ ਊਠ, ...c5 ਅਤੇ ਰਾਣੀ ਨਾਲ d4 ਉੱਤੇ ਵਾਰ ਕਰੋ। ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ, d4 ਉੱਤੇ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ, ਰਾਣੀਆਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ, ਅਤੇ ਹਾਥੀ ਨੂੰ d ਲਾਈਨ ਉੱਤੇ ਰੱਖੋ।" },
