    plan: { en: "Play ...b6 and bring the bishop out to a6 to hit c4. Check with ...Bb4+ to tempt White's bishop to d2, then step back to e7. Build a solid centre with ...c6 and ...d5, swap knights, and castle.", pa: "...b6 ਚੱਲੋ ਅਤੇ c4 ਉੱਤੇ ਵਾਰ ਕਰਨ ਲਈ ਊਠ ਨੂੰ a6 ਉੱਤੇ ਬਾਹਰ ਲਿਆਓ। ...Bb4+ ਨਾਲ ਸ਼ਹਿ ਦਿਓ ਤਾਂ ਜੋ ਚਿੱਟੇ ਦਾ ਊਠ d2 ਉੱਤੇ ਆ ਜਾਵੇ, ਫਿਰ e7 ਉੱਤੇ ਪਿੱਛੇ ਹਟੋ। ...c6 ਅਤੇ ...d5 ਨਾਲ ਪੱਕਾ ਕੇਂਦਰ ਬਣਾਓ, ਘੋੜਿਆਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਰੋ, ਅਤੇ ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ।" },
