        3: { en: "The Petroff: attack e4 back.", pa: "ਪੈਤ੍ਰੋਫ਼: e4 ਉੱਤੇ ਬਦਲੇ ਵਿੱਚ ਹਮਲਾ ਕਰੋ।" },
