    plan: { en: "Against the Italian bishop, bring both knights out at once and hit e4. Against the quiet d3 line, develop with ...Be7, castle, guard e5 with ...d6, then chase White's bishop off its diagonal with ...Na5 and take space with ...c5.", pa: "ਇਤਾਲਵੀ ਊਠ ਦੇ ਸਾਹਮਣੇ ਦੋਵੇਂ ਘੋੜੇ ਇਕੱਠੇ ਬਾਹਰ ਕੱਢੋ ਅਤੇ e4 ਉੱਤੇ ਵਾਰ ਕਰੋ। ਸ਼ਾਂਤ d3 ਵਾਲੀ ਲਾਈਨ ਦੇ ਸਾਹਮਣੇ ...Be7 ਨਾਲ ਮੋਹਰੇ ਬਾਹਰ ਕੱਢੋ, ਕਿਲ੍ਹੇਬੰਦੀ ਕਰੋ, ...d6 ਨਾਲ e5 ਦੀ ਰਾਖੀ ਕਰੋ, ਫਿਰ ...Na5 ਨਾਲ ਚਿੱਟੇ ਦੇ ਊਠ ਨੂੰ ਉਸ ਦੇ ਤਿਰਛੇ ਰਾਹ ਤੋਂ ਭਜਾਓ ਅਤੇ ...c5 ਨਾਲ ਥਾਂ ਹਾਸਲ ਕਰੋ।" },
