        15: { en: "Hit the knight that guards e4.", pa: "e4 ਦੀ ਰਾਖੀ ਕਰਨ ਵਾਲੇ ਘੋੜੇ ਉੱਤੇ ਵਾਰ ਕਰੋ।" },
